package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.identidad.CatalogoPlazos.*;import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class MotorPlazosTest {
 Politica p(String modo,String cal){return new Politica("TEST_REG","v1","REGISTRO_GESTION",modo,172800,cal,cal==null?null:"v1","INSTITUCION",null,null,null,null,Instant.parse("2026-01-01T00:00:00Z"),Instant.parse("2027-01-01T00:00:00Z"),"ACTIVA","SINTETICO","a".repeat(64));}
 Calendario c(List<LocalDate> feriados){return new Calendario("TEST_CAL","v1","America/Santiago",LocalDate.parse("2026-01-01"),LocalDate.parse("2027-01-01"),java.util.stream.IntStream.rangeClosed(1,5).mapToObj(i->new Franja(i,"09:00","17:00")).toList(),feriados,"SINTETICO","b".repeat(64));}
 Instant local(String v){return LocalDateTime.parse(v).atZone(ZoneId.of("America/Santiago")).toInstant();}
 @Test void corridasSon48HorasRealesConLimiteInclusivoYPrecisionDeMilisegundos(){var start=Instant.parse("2026-11-01T13:00:00Z");var due=start.plusSeconds(172800);var exact=MotorPlazos.medir(start,due,p("CORRIDAS",null),null);assertEquals("DENTRO_PLAZO",exact.resultado());assertEquals(172800000,exact.transcurridoMs());assertEquals(due,exact.vencimiento());assertEquals("FUERA_PLAZO",MotorPlazos.medir(start,due.plusMillis(1),p("CORRIDAS",null),null).resultado());}
 @Test void corridasNoAsumenUnOffsetFijoDeSantiago(){var z=ZoneId.of("America/Santiago");var t=z.getRules().nextTransition(Instant.parse("2026-01-01T00:00:00Z"));assertNotNull(t);var a=t.getInstant().minusSeconds(86400);var due=MotorPlazos.medir(a,a,p("CORRIDAS",null),null).vencimiento();assertEquals(Duration.ofHours(48),Duration.between(a,due));assertNotEquals(a.atZone(z).getOffset(),due.atZone(z).getOffset());}
 @Test void habilesUsaJornadaYSoloFeriadosExplicitos(){var a=local("2026-11-02T16:00:00");var cal=c(List.of());var due=local("2026-11-10T16:00:00");assertEquals(due,MotorPlazos.medir(a,due,p("HABILES","TEST_CAL"),cal).vencimiento());var holiday=c(List.of(LocalDate.parse("2026-11-03")));assertEquals(local("2026-11-11T16:00:00"),MotorPlazos.medir(a,due,p("HABILES","TEST_CAL"),holiday).vencimiento());assertEquals(40*3600000L,MotorPlazos.medir(a,due,p("HABILES","TEST_CAL"),holiday).transcurridoMs());}
 @Test void finDeSemanaNoConsumeHorasHabilesNiSeConfundeConResolucion(){var a=local("2026-11-02T16:00:00");var friday=local("2026-11-06T17:00:00");var sunday=local("2026-11-08T15:00:00");assertEquals(MotorPlazos.medir(a,friday,p("HABILES","TEST_CAL"),c(List.of())).transcurridoMs(),MotorPlazos.medir(a,sunday,p("HABILES","TEST_CAL"),c(List.of())).transcurridoMs());}
 @Test void calendarioSinCoberturaNoDeclaraIncumplimientoNiInventaMasJornadas(){var shortCal=new Calendario("TEST_CAL","v1","America/Santiago",LocalDate.parse("2026-11-02"),LocalDate.parse("2026-11-04"),c(List.of()).jornada(),List.of(),"SINTETICO","a".repeat(64));var e=assertThrows(FalloTecnico.class,()->MotorPlazos.medir(local("2026-11-02T09:00:00"),local("2026-11-02T10:00:00"),p("HABILES","TEST_CAL"),shortCal));assertEquals(409,e.status);assertEquals("CALENDARIO_NO_CUBRE_VENCIMIENTO",e.code);}
 @Test void jornadaConCambioHorarioAmbiguoFallaCerrada(){var z=ZoneId.of("America/Santiago");var t=z.getRules().nextTransition(Instant.parse("2026-01-01T00:00:00Z"));assertNotNull(t);var boundary=(t.isOverlap()?t.getDateTimeAfter():t.getDateTimeBefore()).plusMinutes(30);assertNotEquals(1,z.getRules().getValidOffsets(boundary).size());var d=boundary.toLocalDate();var time=boundary.toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"));var cal=new Calendario("TEST_CAL","v1","America/Santiago",d.minusDays(1),d.plusDays(20),List.of(new Franja(d.getDayOfWeek().getValue(),time,"24:00")),List.of(),"SINTETICO","a".repeat(64));var start=d.atStartOfDay(z).toInstant();var e=assertThrows(FalloTecnico.class,()->MotorPlazos.medir(start,start,p("HABILES","TEST_CAL"),cal));assertEquals("JORNADA_HORARIA_AMBIGUA",e.code);}
 @Test void fechaDeRegistroAnteriorOCalendarioAusenteNoSonUnaMedicionValida(){var now=Instant.parse("2026-11-07T12:00:00Z");assertEquals("FECHAS_NO_COMPARABLES",assertThrows(FalloTecnico.class,()->MotorPlazos.medir(now,now.minusMillis(1),p("CORRIDAS",null),null)).code);assertEquals("CALENDARIO_NO_ACREDITADO",assertThrows(FalloTecnico.class,()->MotorPlazos.medir(now,now,p("HABILES","TEST_CAL"),null)).code);}
}
